rows=[];viol=[]
for fp in sorted(glob.glob(str(ROOT/'data/validation/prompt-b-*.json'))):
 p=Path(fp); d=json.loads(p.read_text()); defects=d.get('closed_defects')
 if not defects:continue
 rel=p.relative_to(ROOT).as_posix(); owner=owner_map.get(p.name)
 if not owner:viol.append(f'owner-map-missing:{p.name}');continue
 if d.get('status') not in ('PASS','CLOSED','COMPLETED') and not str(d.get('status','')).startswith('CLOSED_'):viol.append(f'source-receipt-not-closed:{p.name}:{d.get("status")}')
 for x in defects:
  fix=x.get('fix') or x.get('resolution'); did=x.get('id'); cls=x.get('class') or ('HARNESS_OR_VALIDATION_DEFECT' if p.name=='prompt-b-test-suite-audit.json' and did!='mock-runtime-self-promoted-t3' else 'PRODUCT_OR_ARCHITECTURE_DEFECT')
  if not did or not fix:viol.append(f'incomplete-defect-record:{p.name}:{did}');continue
  rows.append({'id':did,'classification':cls,'canonical_owner':owner,'root_cause_record':x.get('finding') or x.get('class') or did,'resolution':fix,'regression_receipt':rel,'regression_receipt_sha256':sha(rel),'closure_pipeline':['discover','classify','canonical-owner','root-cause','fix','regression-test','focused-verification','full-verification','docs-parity','local-commit','ledger','adjacent-reaudit']})
