 {'id':'fresh-consumer-agent-projection-assertion-drift','classification':'ACCEPTANCE_HARNESS_DEFECT','canonical_owner':'scripts/run-fresh-consumer-acceptance.py','root_cause_record':'fresh-consumer assertion depended on a narrower agent response shape than the native endpoint contract','resolution':'acceptance consumes the live agent endpoint and verifies canonical coder projection without invented fields','proof':'data/validation/fresh-consumer-opencode-1.18.18.json','anchor':'coder_agent_observed'},
 {'id':'failure-injection-disk-fixture-not-failing','classification':'TEST_FIXTURE_DEFECT','canonical_owner':'plugin/test/q5-failure-injection.test.mjs','root_cause_record':'initial disk-failure fixture did not force a filesystem write error','resolution':'state root is a regular file so persistence deterministically fails ENOTDIR before any committed state','proof':'plugin/test/q5-failure-injection.test.mjs','anchor':'Q5 injected disk write failure throws synchronously'},
