 {'id':'user-journey-unsupported-primitive-assumption','classification':'TEST_ASSERTION_DRIFT','canonical_owner':'plugin/test/q6-user-journey-acceptance.test.mjs','root_cause_record':'test confused documented native primitive metadata with a runtime support claim','resolution':'journey asserts UNSUPPORTED/OBSERVED plus forbidden fake behavior rather than requiring primitive metadata to be absent','proof':'plugin/test/q6-user-journey-acceptance.test.mjs','anchor':'Q6 unsupported journey is truthful'},
