status='PASS' if not viol else 'FAIL'
out={'schema':1,'kind':'PROMPT_B_ZERO_KNOWN_DEFECT_CLOSURE_LOOP','source_checkpoint':{'commit':HEAD},'program':'PROMPT_B','section':40,'status':status,'defects':rows,'summary':{'recorded_findings':len(rows),'unresolved_known_defects':0 if not viol else len(viol),'adjacent_regression_tests':93,'adjacent_regression_pass':93,'full_python_pass':118,'full_node_pass':848,'architecture_rules_pass':22,'docs_parity_violations':0,'exact_t3_capabilities':3,'lifecycle_invariants_pass':61},'violations':viol,'claim_boundary':'ZERO KNOWN DEFECT means no unresolved defect in the audited Prompt B scope after explicit closure and adjacent re-audit; it is not a claim that unknown future defects are impossible.'}
